static void stretch_table_columns(int32_t id) {
    if (id <= 0 || id >= JN_UI_MAX || g_hwnds[id] == NULL) {
        return;
    }
    HWND lv = g_hwnds[id];
    int cols = g_col_count[id];
    if (cols <= 0) {
        HWND hdr = ListView_GetHeader(lv);
        if (hdr != NULL) {
            cols = Header_GetItemCount(hdr);
        }
    }
    if (cols <= 0) {
        return;
    }
    if (cols > JN_UI_MAX_COLS) {
        cols = JN_UI_MAX_COLS;
    }
    RECT rc;
    GetClientRect(lv, &rc);
    int view = rc.right - rc.left - 4;
    if (view < 80) {
        return;
    }
    int widths[JN_UI_MAX_COLS];
    int flex[JN_UI_MAX_COLS];
    int c;
    int total = 0;
    int flexSum = 0;
    for (c = 0; c < cols; c++) {
        int lp = g_col_width_lp[id][c];
        if (lp <= 0) {
            lp = (c == 0) ? 220 : 100;
        }
        if (g_col_max_lp[id][c] > 0 && lp > g_col_max_lp[id][c]) {
            lp = g_col_max_lp[id][c];
        }
        widths[c] = lp;
        flex[c] = g_col_flex[id][c];
        if (flex[c] > 0) {
            flexSum += flex[c];
        }
        total += lp;
    }
    if (flexSum <= 0) {
        flex[0] = 1;
        flexSum = 1;
    }
    /* Fit all columns into the view: shrink or grow via flex (honoring max caps). */
    if (total > view) {
        /* Shrink trailing / flex columns first so name+CPU+mem+PID stay readable. */
        int need = total - view;
        int pass;
        for (pass = 0; pass < 3 && need > 0; pass++) {
            int avail = 0;
            int taken = 0;
            int take;
            int sweep;
            for (c = 0; c < cols; c++) {
                int eligible = 0;
                int floor = 48;
                if (pass == 0) {
                    /* Prefer shrinking user/threads (last two) and other flex cols. */
                    eligible = (flex[c] > 0) || (c >= cols - 2);
                    floor = (c >= cols - 2) ? 0 : 56;
                } else if (pass == 1) {
                    eligible = flex[c] > 0 || c == 0;
                    floor = (c == 0) ? 120 : 56;
                } else {
                    eligible = 1;
                    floor = 48;
                }
                if (eligible && widths[c] > floor) {
                    avail += widths[c] - floor;
                }
            }
            if (avail <= 0) {
                continue;
            }
            take = need < avail ? need : avail;
            for (c = 0; c < cols; c++) {
                int eligible = 0;
                int floor = 48;
                if (pass == 0) {
                    eligible = (flex[c] > 0) || (c >= cols - 2);
                    floor = (c >= cols - 2) ? 0 : 56;
                } else if (pass == 1) {
                    eligible = flex[c] > 0 || c == 0;
                    floor = (c == 0) ? 120 : 56;
                } else {
                    eligible = 1;
                    floor = 48;
                }
                if (eligible && widths[c] > floor) {
                    int room = widths[c] - floor;
                    int cut = take * room / avail;
                    widths[c] -= cut;
                    taken += cut;
                }
            }
            for (sweep = 0; sweep < 4 && taken < take; sweep++) {
                for (c = cols - 1; c >= 0 && taken < take; c--) {
                    int floor = 48;
                    if (pass == 0 && c >= cols - 2) {
                        floor = 0;
                    } else if (pass == 1 && c == 0) {
                        floor = 120;
                    } else if (pass == 1) {
                        floor = 56;
                    }
                    if (widths[c] > floor) {
                        widths[c]--;
                        taken++;
                    }
                }
            }
            need -= taken;
        }
    } else if (total < view) {
        int extra = view - total;
        int iter;
        for (iter = 0; iter < 32 && extra > 0; iter++) {
            int fsum = 0;
            int given = 0;
            int firstEligible = -1;
            for (c = 0; c < cols; c++) {
                int cap = g_col_max_lp[id][c];
                if (flex[c] > 0 && (cap <= 0 || widths[c] < cap)) {
                    fsum += flex[c];
                    if (firstEligible < 0) {
                        firstEligible = c;
                    }
                }
            }
            if (fsum <= 0) {
                break; /* every flex column is capped: leave the rest unused */
            }
            for (c = 0; c < cols; c++) {
                int cap = g_col_max_lp[id][c];
                if (flex[c] > 0 && (cap <= 0 || widths[c] < cap)) {
                    int add = extra * flex[c] / fsum;
                    if (cap > 0 && widths[c] + add > cap) {
                        add = cap - widths[c];
                    }
                    widths[c] += add;
                    given += add;
                }
            }
            if (given <= 0) {
                /* rounding starved everyone: hand out a single pixel */
                widths[firstEligible]++;
                given = 1;
            }
            extra -= given;
        }
    }
    for (c = 0; c < cols; c++) {
        ListView_SetColumnWidth(lv, c, widths[c]);
    }
}

void jnative_ui_set_bounds(int32_t id, int32_t x, int32_t y, int32_t w, int32_t h) {
    if (id > 0 && id < JN_UI_MAX && g_hwnds[id] != NULL) {
        HWND hwnd = g_hwnds[id];
        if (g_kinds[id] == JN_UI_KIND_WINDOW) {
            apply_outer_client_size(hwnd, w, h);
            if (x != 0 || y != 0) {
                SetWindowPos(hwnd, NULL, x, y, 0, 0,
                        SWP_NOSIZE | SWP_NOZORDER | SWP_NOACTIVATE);
            }
            return;
        }
        MoveWindow(hwnd, x, y, w, h, TRUE);
        if (g_kinds[id] == JN_UI_KIND_TABLEVIEW || g_kinds[id] == JN_UI_KIND_LISTVIEW) {
            stretch_table_columns(id);
        }
    }
}
