        wchar_t *wmsg = utf8_to_wide(message);
        UINT flags = MB_OK;
        if (type == 1) flags = MB_YESNO;
        if (type == 2) flags = MB_OK | MB_ICONERROR;
        HWND owner = (windowId > 0 && windowId < JN_UI_MAX) ? g_hwnds[windowId] : NULL;
